import subprocess
import sys
from fastapi import APIRouter, Depends, HTTPException, Security
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
from .scripts import SCRIPTS_DB

router = APIRouter(prefix="/api/v1/panels", tags=["Panels Mobile"])

# Token validation setup (Matches QR code generated by BuilderUI)
security = HTTPBearer()
VALID_AUTH_TOKEN = "hackathon-secret-key-123"  # Store in env file in production

def verify_token(credentials: HTTPAuthorizationCredentials = Security(security)):
    """Ensures incoming requests from Cloudflare Tunnel carry the valid token."""
    if credentials.credentials != VALID_AUTH_TOKEN:
        raise HTTPException(status_code=403, detail="Invalid token")
    return credentials.credentials

@router.get("/widgets", dependencies=[Depends(verify_token)])
def get_active_widgets():
    """
    Called by mobile PWA on load. Extracts and returns only 
    the UI widget dynamic structure for rendering panels.
    """
    widgets = []
    for s_id, s_data in SCRIPTS_DB.items():
        widgets.append({
            "script_id": s_id,
            "name": s_data["name"],
            "widget": s_data["widget"]
        })
    return {"widgets": widgets}

@router.post("/run/{script_id}", dependencies=[Depends(verify_token)])
def execute_script(script_id: str, payload: dict = None):
    """
    Triggered when user interacts with a widget on mobile.
    Executes script in a sandboxed process with a 5-second timeout.
    """
    if script_id not in SCRIPTS_DB:
        raise HTTPException(status_code=404, detail="Script not found")

    script = SCRIPTS_DB[script_id]
    code = script["code"]

    try:
        # Execute Python code safely in a separate process
        process = subprocess.run(
            [sys.executable, "-c", code],
            capture_output=True,
            text=True,
            timeout=5  # Prevent frozen/infinite-loop scripts
        )

        return {
            "status": "success",
            "returncode": process.returncode,
            "stdout": process.stdout.strip(),
            "stderr": process.stderr.strip()
        }

    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=504, detail="Script execution timed out (5s limit exceeded)")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Execution error: {str(e)}")